// Package cruntime assembles the standalone C runtime linked into native
// programs generated by Kryndel. It has no dependency on compiler or runtime
// state, so the emitted C source can be verified independently.
package cruntime

import "strings"

// cRuntimeParts is the single source order for emitted C and C runtime tests.
// Keep dependencies in order: the common value model, primitive operations,
// indexing and collections, host APIs, then extended cryptography.
var cRuntimeParts = [...]string{
	cRuntimePrelude,
	cRuntimeFormatting,
	cRuntimeDisplay,
	cRuntimeEqualityArithmetic,
	cRuntimeOutput,
	cRuntimeBuiltins,
	cRuntimeIndex,
	cRuntimeFileBase,
	cRuntimeSHA256,
	cRuntimeJSON,
	cRuntimeFileSystem,
	cRuntimeProcess,
	cRuntimeConcurrency,
	cRuntimeDispatch,
	cRuntimeCollections,
	cRuntimeTCP,
	cRuntimeHTTP,
	cRuntimeSQLite,
	cRuntimeCrypto,
}

// Source returns the complete C runtime source in dependency order.
func Source() string {
	var source strings.Builder
	for _, part := range cRuntimeParts {
		source.WriteString(part)
	}
	return source.String()
}
